<section class="container page-section"><div class="breadcrumbs"><a href="/">Home</a><span>/</span><span>Your cart</span></div><div class="page-title-row"><div><span class="eyebrow">YOUR SELECTION</span><h1>Your shopping cart</h1><p><?= count($items) ?> different item<?= count($items)===1?'':'s' ?> ready when you are.</p></div><a class="text-link" href="/products">Continue shopping ↗</a></div><?php if(!$items): ?><div class="empty-state"><div class="empty-icon">🛒</div><h2>Your cart is taking a little break</h2><p>Add something useful, lovely, or just-for-fun to get started.</p><a class="btn btn-primary" href="/products">Explore the shop</a></div><?php else: ?><div class="cart-layout"><div class="cart-items"><?php foreach($items as $item): ?><article class="cart-item"><a href="/product?slug=<?= e($item['slug']) ?>" class="cart-item-image"><img src="<?= e(product_image($item)) ?>" alt="<?= e($item['name']) ?>"></a><div class="cart-item-info"><span class="product-category"><?= e($item['category']) ?></span><a href="/product?slug=<?= e($item['slug']) ?>" class="cart-item-name"><?= e($item['name']) ?></a><div class="stock-line in-stock"><?= (int)$item['stock']>0?'In stock':'Low stock' ?></div><div class="cart-row-actions"><form method="post" action="/cart/update"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= (int)$item['id'] ?>"><label class="quantity-label">Qty <select name="quantity" onchange="this.form.submit()"><?php for($q=1;$q<=max(1,min(99,(int)$item['stock']));$q++): ?><option value="<?= $q ?>" <?= $q==(int)$item['quantity']?'selected':'' ?>><?= $q ?></option><?php endfor; ?></select></label></form><span class="action-separator">|</span><form method="post" action="/cart/remove"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= (int)$item['id'] ?>"><button class="link-button">Remove</button></form></div></div><strong class="cart-item-price"><?= money($item['price']*$item['quantity']) ?></strong></article><?php endforeach; ?><div class="cart-continue"><a class="text-link" href="/products">← Continue shopping</a></div></div><aside class="order-summary"><h2>Order summary</h2><div class="summary-line"><span>Subtotal</span><strong><?= money($total) ?></strong></div><div class="summary-line"><span>Shipping</span><span><?= $total>=75?'FREE':money(5.99) ?></span></div><p class="summary-note"><?= $total<75?'Spend '.money(75-$total).' more for free shipping.':'You unlocked free shipping.' ?></p><div class="summary-total"><span>Estimated total</span><strong><?= money($total+($total>=75?0:5.99)) ?></strong></div><p class="tax-note">Tax calculated during checkout.</p><?php if(is_logged_in()): ?><a href="/checkout" class="btn btn-primary btn-block">Continue to checkout <span>→</span></a><?php else: ?><a href="/sign-in" class="btn btn-primary btn-block">Sign in to checkout <span>→</span></a><p class="checkout-note">Your cart will be merged after sign in.</p><?php endif; ?><div class="secure-note">♧ Demo checkout · No real payment</div></aside></div><?php endif; ?></section>